#include "gateway_warehouse_page.h"

const char GATEWAY_WAREHOUSE_PAGE[] =
"<!doctype html><html lang='vi'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='color-scheme' content='dark'><title>AUBOT | Thiết lập kho</title><link rel='stylesheet' href='/ui.css'><style>"
".warehouse-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.tile{min-height:140px;padding:15px;border:1px solid var(--line);border-radius:11px;background:var(--glass);color:var(--text);text-align:left}.tile .position{color:#92a8e8;font-size:10px;font-weight:850}.tile .code{display:block;margin-top:6px;font-size:17px}.tile .state{display:block;margin-top:17px;font-weight:850}.tile .meta{display:block;margin-top:6px;color:var(--muted);font-size:11px}.tile.EMPTY{border-color:rgba(52,211,153,.4)}.tile.OCCUPIED{border-color:rgba(251,191,36,.48)}.section{margin-top:14px;padding-top:14px;border-top:1px solid var(--line2)}.dialog-tabs{display:flex;gap:6px;margin-bottom:16px;padding:4px;border:1px solid var(--line2);border-radius:10px;background:var(--glass2)}.dialog-tabs .btn{flex:1;border:0;color:var(--muted)}.dialog-tabs .btn.active{background:rgba(52,211,153,.14);color:#a7f3d0}.tab-pane.hidden{display:none}.auto-laser{min-height:46px;display:flex;align-items:center;padding:9px 11px;border:1px solid var(--line);border-radius:9px;background:var(--glass2);font-weight:750}.runtime{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.runtime div{padding:9px;border:1px solid var(--line2);border-radius:8px;background:var(--glass2)}.runtime small{display:block;color:var(--muted)}.group-option:disabled{color:#64748b}@media(max-width:760px){.warehouse-grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:390px){.warehouse-grid,.runtime{grid-template-columns:1fr}}</style></head><body data-page='factory'><div class='shell'>"
"<header class='hero'><div class='brand'><img class='logo' src='/logo.png' alt='AUBOT'><div><div class='eyebrow'>AUBOT · WAREHOUSE GATEWAY</div><h1>Thiết lập vị trí kho</h1><p>Gán độc lập vị trí kho với nhóm Laser</p></div></div><div data-app-user></div></header><div data-system-bar></div><nav class='nav' data-app-nav></nav><section class='toolbar'><div class='segmented'><button class='btn' id='p8'>8 VỊ TRÍ</button><button class='btn' id='p12'>12 VỊ TRÍ</button></div><div id='summary'>Đang đọc…</div></section><main id='grid' class='warehouse-grid'></main></div>"
"<dialog id='dlg'><header class='dialog-head'><div><div class='eyebrow'>THIẾT LẬP KHO</div><h2 id='title'>Vị trí</h2></div><button class='btn ghost' type='button' id='close'>Đóng</button></header><form id='form' class='dialog-body'><nav class='dialog-tabs' aria-label='Nội dung cấu hình'><button class='btn active' type='button' id='positionTab'>Vị trí kho</button><button class='btn' type='button' id='laserTab'>Cấu hình Laser</button></nav><div class='tab-pane' id='positionPane'><section><div class='fields'><label class='field'><span>Mã kho</span><input id='code' maxlength='15' required></label><label class='field'><span>Tên vị trí</span><input id='name' maxlength='31'></label><label class='switch-line full'><span>Sử dụng vị trí kho này</span><input id='enabled' type='checkbox'></label></div></section>"
"<section class='section'><h3>Nhóm Laser</h3><div class='fields'><label class='field full'><span>Nhóm phụ trách vị trí</span><select id='group'></select></label><label class='field full'><span>Dải ID của nhóm</span><input id='range' readonly></label></div><p class='hint'>Chỉ nhóm có ít nhất một Laser online mới chọn được. Một nhóm chỉ gán cho một vị trí.</p></section><section class='section'><h3>Realtime</h3><div id='runtime' class='runtime'></div></section></div>"
"<div class='tab-pane hidden' id='laserPane'><section><h3>Cấu hình Laser</h3><div class='fields'><div class='field full'><span class='field-label'>Laser được chọn tự động</span><div id='laserAuto' class='auto-laser'>Chưa có Laser online</div><input id='laser' type='hidden' value='0'></div></div></section><section class='section'><h3>Vùng phát hiện</h3><div class='fields'><label class='field'><span>Khoảng cách (mm)</span><input id='distance' type='number' min='0' max='1200'></label><label class='field'><span>Khẩn cấp (mm)</span><input id='emergency' type='number' min='0' max='1200'></label><label class='switch-line full'><span>Bật Laser phát hiện hàng hóa</span><input id='proximity' type='checkbox'></label></div><details style='margin-top:11px'><summary>Vùng quan sát 8×8 nâng cao</summary><div class='details-body fields'><label class='field'><span>Mặt nạ hàng</span><input id='row' type='number' min='0' max='255'></label><label class='field'><span>Mặt nạ cột</span><input id='col' type='number' min='0' max='255'></label></div></details></section></div>"
"<div id='message' class='message' aria-live='polite'></div><p id='hint' class='hint'>Lưu mapping trước khi áp dụng xuống Laser.</p><div class='dialog-actions'><button class='btn danger' type='button' id='clear'>Xóa gán nhóm</button><button class='btn secondary' type='button' id='apply' disabled>Áp dụng xuống Laser</button><button class='btn primary' id='save'>Lưu mapping</button></div></form></dialog>"
"<script src='/ui.js'></script><script>const $=x=>document.getElementById(x),esc=x=>String(x??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c])),label=s=>s==='EMPTY'?'KHÔNG CÓ HÀNG':s==='OCCUPIED'?'CÓ HÀNG':'CHƯA XÁC ĐỊNH';let snap,groups=[],nodes=[],editing=0,saved='',statusTimer,headerTimer;const nodeById=Array(65);function message(t,c=''){$('message').textContent=t;$('message').className='message '+c}function sig(x){return [x.position_id,x.group_id,x.laser_id,String(x.warehouse_code||''),String(x.warehouse_name||''),Number(x.config_distance_mm??x.distance_mm),Number(x.config_emergency_mm??x.emergency_mm),Number(x.low_col),Number(x.high_row),Number(x.enabled),Number(x.proximity_enabled??x.proximity)].join('|')}function formData(){return {position_id:editing,group_id:$('group').value,laser_id:$('laser').value,warehouse_code:$('code').value.trim(),warehouse_name:$('name').value.trim(),distance_mm:$('distance').value,emergency_mm:$('emergency').value,low_col:$('col').value,high_row:$('row').value,enabled:$('enabled').checked?1:0,proximity:$('proximity').checked?1:0}}function runtime(p){$('runtime').innerHTML=`<div><small>Kho</small><b>${label(p.state)}</b></div><div><small>Nhóm Laser</small><b>${p.group_id?'NHÓM '+p.group_id:'CHƯA GÁN'}</b></div><div><small>Cảm biến</small><b>${p.sensor_online?'ONLINE':'OFFLINE'}</b></div>`}function render(){const list=snap.positions||[];$('p8').classList.toggle('active',snap.profile==='GROUP_8');$('p12').classList.toggle('active',snap.profile==='GROUP_12');$('summary').textContent=`${snap.group_count} vị trí · ${snap.configured} đã cấu hình · ${snap.occupied} có hàng`;$('grid').innerHTML=list.map(p=>`<button class='tile ${p.state}' data-position='${p.position_id}'><span class='position'>VỊ TRÍ ${p.position_id}</span><strong class='code'>${esc(p.warehouse_code||'Chưa cấu hình')}</strong><span class='state'>${label(p.state)}</span><span class='meta'>${p.group_id?'Nhóm Laser '+p.group_id:'Chưa gán nhóm Laser'}</span></button>`).join('');document.querySelectorAll('[data-position]').forEach(b=>b.onclick=()=>openPosition(Number(b.dataset.position)));if($('dlg').open&&editing)runtime(list[editing-1])}async function loadStatus(){clearTimeout(statusTimer);if(document.hidden){statusTimer=setTimeout(loadStatus,10000);return}try{snap=await gw.fetchJson('/api/factory/status');render()}catch(e){}statusTimer=setTimeout(loadStatus,1800)}async function loadLasers(){const d=await gw.fetchJson('/api/factory/lasers');groups=d.groups||[];nodes=d.nodes||[];nodes.forEach(n=>nodeById[n.id]=n)}function groupOptions(current){return '<option value=0>Chưa gán nhóm</option>'+groups.map(g=>{const used=snap.positions.find(p=>p.position_id!==editing&&p.enabled&&p.group_id===g.id),disabled=(g.online<1||used)&&g.id!==current;return `<option class='group-option' value='${g.id}' ${disabled?'disabled':''}>Nhóm ${g.id} · ID ${g.first}–${g.last} · ${g.online} online${used?' · đang ở vị trí '+used.position_id:''}</option>`}).join('')}function syncLaser(){const id=Number($('group').value),g=groups.find(x=>x.id===id);if(!g){$('range').value='Ch\u01b0a ch\u1ecdn nh\u00f3m';$('laser').value=0;$('laserAuto').textContent='Ch\u01b0a ch\u1ecdn nh\u00f3m Laser';return}$('range').value=`ID ${g.first}\u2013${g.last}`;const online=Array.from({length:g.last-g.first+1},(_,i)=>g.first+i).find(id=>nodeById[id]?.alive);$('laser').value=online||0;$('laserAuto').textContent=online?'ID '+online+' \u00b7 ONLINE':'Nh\u00f3m ch\u01b0a c\u00f3 Laser online'}function showTab(name){const laser=name==='laser';$('positionPane').classList.toggle('hidden',laser);$('laserPane').classList.toggle('hidden',!laser);$('positionTab').classList.toggle('active',!laser);$('laserTab').classList.toggle('active',laser)}function openPosition(id){editing=id;const p=snap.positions[id-1];$('title').textContent='Vị trí '+id;$('code').value=p.warehouse_code||'';$('name').value=p.warehouse_name||'';$('enabled').checked=p.enabled;$('group').innerHTML=groupOptions(p.group_id);$('group').value=p.group_id||0;$('distance').value=p.config_distance_mm??600;$('emergency').value=p.config_emergency_mm??300;$('row').value=p.high_row??0;$('col').value=p.low_col??0;$('proximity').checked=p.proximity_enabled;syncLaser();runtime(p);showTab('position');saved=sig(p);message('');syncApply();$('dlg').showModal()}function syncApply(){const p=snap.positions[editing-1],same=sig(formData())===saved,ready=p.enabled&&p.group_id&&p.laser_id&&same;$('apply').disabled=!ready;$('hint').textContent=ready?'Mapping đã lưu; có thể áp dụng vùng phát hiện xuống Laser.':same?'Vị trí phải được bật và gán nhóm Laser online.':'Hãy lưu mapping trước khi áp dụng xuống Laser.'}function errorVi(e){return {DUPLICATE_LASER_GROUP:'Nhóm Laser đã được gán cho vị trí khác. Hãy xóa gán cũ trước.',LASER_GROUP_OFFLINE:'Nhóm này chưa có Laser nào online.',LASER_OUT_OF_GROUP:'Laser tham chiếu không thuộc nhóm đã chọn.',DUPLICATE_LASER_ID:'Laser này đã được sử dụng.',DUPLICATE_WAREHOUSE_CODE:'Mã kho đã được sử dụng.',INVALID_DISTANCE:'Khoảng cách không hợp lệ.',INVALID_GROUP:'Vị trí hoặc nhóm không hợp lệ.'}[e]||e}async function save(data){const r=await fetch('/api/factory/warehouse',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams(data)});if(!r.ok)throw Error(await r.text());snap=await gw.fetchJson('/api/factory/status');render();saved=sig(snap.positions[editing-1]);syncApply()}$('positionTab').onclick=()=>showTab('position');$('laserTab').onclick=()=>showTab('laser');$('group').onchange=()=>{syncLaser();message('');syncApply()};$('form').oninput=syncApply;$('form').onsubmit=async e=>{e.preventDefault();const b=$('save');b.disabled=true;message('Đang lưu…');try{await save(formData());message('Đã lưu mapping.','ok')}catch(x){message(errorVi(x.message),'bad')}finally{b.disabled=false}};$('clear').onclick=async()=>{if(!confirm('Xóa gán nhóm khỏi vị trí này?'))return;const p=formData();p.enabled=0;p.group_id=0;p.laser_id=0;try{await save(p);$('dlg').close()}catch(x){message(errorVi(x.message),'bad')}};$('apply').onclick=async()=>{if($('apply').disabled)return;try{const r=await fetch('/api/factory/laser/apply',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({position_id:editing})});if(!r.ok)throw Error(await r.text());message('Đã gửi cấu hình xuống Laser.','ok')}catch(x){message(errorVi(x.message),'bad')}};async function profile(p){if(snap.profile===p)return;const r=await fetch('/api/factory/profile',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},body:new URLSearchParams({profile:p,clear_conflicts:0})});if(!r.ok)alert('Mapping hiện tại xung đột với số vị trí mới.');else{await loadLasers();loadStatus()}}$('p8').onclick=()=>profile('GROUP_8');$('p12').onclick=()=>profile('GROUP_12');$('close').onclick=()=>$('dlg').close();document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadStatus()});Promise.all([loadLasers(),gw.fetchJson('/api/factory/status').then(x=>snap=x)]).then(()=>{render();loadStatus()})</script></body></html>";
